import pandas as pd


def _sig_part(val):
    """RTRIM(COALESCE(val, '')) semantics."""
    if val is None:
        return ''
    try:
        if pd.isna(val):
            return ''
    except (TypeError, ValueError):
        pass
    return str(val).rstrip(' ')


def _signature(city, tier):
    return _sig_part(city) + '|' + _sig_part(tier)


def run(inputs: dict) -> dict:
    dim = inputs['DIM_MEMBER'].copy()
    stg = inputs['STG_MEMBER'].copy()

    # Work on a list of dict records so we can mutate "in place" the same
    # way the stored procedure would UPDATE existing rows and INSERT new
    # ones, while preserving all rows not touched by any staged record.
    records = dim.to_dict('records')

    for s in stg.to_dict('records'):
        mid = s['member_id']

        current_idx = None
        for i, r in enumerate(records):
            if r.get('member_id') == mid:
                ic = r.get('is_current')
                try:
                    is_cur = int(ic) == 1
                except (TypeError, ValueError):
                    is_cur = False
                if is_cur:
                    current_idx = i
                    break

        if current_idx is None:
            # No current row for this member -> plain insert.
            records.append({
                'member_id': mid,
                'city': s.get('city'),
                'tier': s.get('tier'),
                'eff_start_date': s.get('update_date'),
                'eff_end_date': None,
                'is_current': 1,
            })
        else:
            c = records[current_idx]
            staged_sig = _signature(s.get('city'), s.get('tier'))
            current_sig = _signature(c.get('city'), c.get('tier'))

            if staged_sig != current_sig:
                # Close the prior current row.
                c['eff_end_date'] = s.get('update_date')
                c['is_current'] = 0

                # Insert the new current version, stored exactly as staged
                # (no trimming, NULL stays NULL, '' stays '').
                records.append({
                    'member_id': mid,
                    'city': s.get('city'),
                    'tier': s.get('tier'),
                    'eff_start_date': s.get('update_date'),
                    'eff_end_date': None,
                    'is_current': 1,
                })
            # else: signatures match -> no-op, current row untouched.

    out = pd.DataFrame(
        records,
        columns=['member_id', 'city', 'tier', 'eff_start_date', 'eff_end_date', 'is_current'],
    )

    return {'dim_member_out': out}
